def rot(Mh,Pp):
    B=Pp.T@Mh@Pp
    if B.shape[0]==1: return abs(B[0,0]), (0.0 if B[0,0]>0 else np.pi)
    c=(B[0,0]+B[1,1])/2; s=(B[1,0]-B[0,1])/2
    return np.hypot(c,s), np.arctan2(s,c)
